window.AUTH=window.AUTH||{};window.AUTH["17-1606"]={"d":"17-1606","id":"2018/17-1606","n":"Smith v. Berryhill","briefs":[{"k":"petitioner","label":"Brief of petitioner Ricky Lee Smith","date":"2018-12-19","url":"https://www.supremecourt.gov/DocketPDF/17/17-1606/76937/20181219162426879_17-1606.ts.pdf","side":"pet","n":34},{"k":"respondent","label":"Brief of respondent in support of reversal and remand","date":"2018-12-19","url":"https://www.supremecourt.gov/DocketPDF/17/17-1606/76992/20181219203659525_17-1606bsUnitedStates.pdf","side":"res","n":65},{"k":"reply","label":"Reply of petitioner Ricky Lee Smith","date":"2019-02-28","url":"https://www.supremecourt.gov/DocketPDF/17/17-1606/90189/20190228172106663_17-1606.cert.reply.pdf","side":"pet","n":39}],"opinion":"https://www.supremecourt.gov/opinions/18pdf/17-1606_868c.pdf","tr":true,"items":[{"t":"case","label":"Bennett v. Spear","cite":"520 U.S. 154","y":1997,"id":"1996/95-813","sc":1,"op":1,"sum":"In the unanimous decision, announced by Justice Antonin Scalia, the Court ruled that the petitioners had standing to ask for judicial review of the minimum water level setting under the Endangered Species Act. The Act explicitly allows \"any person\" to sue the government over an alleged violation. Justice Scalia asserted this applies to the Secretary's actions over enforcement.","sumSrc":"Oyez","by":{"0":"12, 15","1":"26, 27"}},{"t":"case","label":"Bloodsworth v. Heckler","cite":"703 F.2d 1233","y":1983,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/703/1233/","op":1,"ar":1,"by":{"0":"6, 19","1":"passim","2":"13"}},{"t":"case","label":"Boley v. Colvin","cite":"761 F.3d 803","y":2014,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/761/803/","sum":"Explaining that Sanders held that “one opportunity for judicial review is enough” and refusing to extend Sanders to preclude judicial review of administrative untimeliness decisions.","sumSrc":"brief:0","by":{"0":"18, 22, 24","1":"37, 39, 45","2":"14-15"}},{"t":"case","label":"Bowen v. City of New York","cite":"476 U.S. 467","y":1986,"id":"1985/84-1923","sc":1,"op":7,"sum":"The Social Security Act provides benefits to disabled persons under two programs administered by the Social Security Administration (SSA): the Social Security Disability Insurance Program (SSD) and the Supplemental Security Income Program (SSI). Regulations for both programs establish a five-step \"sequential evaluation\" process for determining eligibility for benefits. The initial determination of whether an …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24","1":"5, 23, 34, 44","2":"passim"}},{"t":"case","label":"Bowen v. Michigan Acad. of Family Physicians","cite":"476 U.S. 667","y":1986,"id":"1985/85-225","sc":1,"op":6,"sum":"In neither 42 U. S. C. § 1395ff (1982 ed. and Supp. II) nor § 1395ii (1982 ed., Supp. II), has Congress barred judicial review of regulations promulgated under Part B of the Medicare program.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"4","2":"16"}},{"t":"case","label":"Brandtner v. Department of Health & Human Servs.","cite":"150 F.3d 1306","y":1998,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/150/1306/","op":1,"by":{"0":"6","1":"16, 33"}},{"t":"case","label":"Califano v. Sanders","cite":"430 U.S. 99","y":1977,"id":"1976/75-1443","sc":1,"op":4,"ar":4,"sum":"1. Section 10 of the Administrative Procedure Act (APA), providing generally for judicial review of actions of federal administrative agencies by persons aggrieved by such actions, does not afford an implied grant to district courts of subject-matter jurisdiction to review a decision of the Secretary of Health, Education, and Welfare not to reopen a previously adjudicated claim for social security benefits. An …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"12, 18, 19","1":"passim","2":"passim"}},{"t":"case","label":"Casey v. Berryhill","cite":"853 F.3d 322","y":2017,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/853/322/","op":1,"sum":"Rejecting SSA’s determination regarding timeliness but explaining that, because there was “no ‘final decision’ on the underlying merits” of the plaintiff ’s benefits application, the merits were “a question for the agency to consider on remand”.","sumSrc":"brief:1","by":{"0":"16","1":"16, 22, 30"}},{"t":"case","label":"Chevron, U.S.A., Inc. v. Natural Res. Def. Council, Inc.","cite":"467 U.S. 837","y":1984,"id":"1983/82-1005","sc":1,"op":4,"sum":"The Supreme Court held that the bubble regulation was a reasonable interpretation of the term “stationary source” in the Clean Air Act. Congress did not have a specific intention for the interpretation of that term, and the EPA’s regulation was a reasonable policy choice. The regulation also provided reasonable accommodations for the many competing interests affected by the Act.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Counts v. Commissioner of Soc. Sec.","cite":"2010 WL 5174498","y":2010,"court":"M.D. Fla.","sum":"Holding that a dismissal was “not based on substantial evidence”.","sumSrc":"brief:0","by":{"0":"22, 23"}},{"t":"case","label":"Cuozzo Speed Techs., LLC v. Lee","cite":"136 S. Ct. 2131","y":2016,"id":"2015/15-446","sc":1,"sum":"The Court held that the Patent Trial and Appeal Board may apply the broadest reasonable interpretation of patent claims during an inter partes review proceeding, and such a proceeding is not judicially reviewable.","sumSrc":"Oyez","by":{"0":"17"}},{"t":"case","label":"Davis v. Colvin","cite":"2013 WL 1174157","y":2013,"court":"M.D. Fla.","sum":"Holding that the Appeals Council’s dismissal on grounds of untimeliness was unfounded.","sumSrc":"brief:0","by":{"0":"22"}},{"t":"case","label":"Department of Housing & Urban Dev. v. Rucker","cite":"535 U.S. 125","y":2002,"id":"2001/00-1770","sc":1,"sum":"The Court held that the Anti-Drug Abuse Act of 1988 unambiguously requires lease terms that vest local public housing authorities with the discretion to evict tenants for the drug-related activity of household members and guests whether or not the tenant knew, or should have known, about the activity.","sumSrc":"Oyez","by":{"0":"14"}},{"t":"case","label":"Epic Sys. Corp. v. Lewis","cite":"138 S. Ct. 1612","y":2018,"id":"2017/16-285","sc":1,"sum":"The Court held that the Federal Arbitration Act requires that arbitration agreements providing for individualized proceedings be enforced.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Limtiaco v. Camacho","cite":"549 U.S. 483","y":2007,"id":"2006/06-116","sc":1,"sum":"The majority opinion by Justice Clarence Thomas held that, contrary to the Guam Supreme Court's interpretation, the phrase must mean the assessed value for tax purposes of property on Guam. \"The word 'tax' modifies 'valuation,' not 'property,'\" the Court reasoned, so \"tax valuation\" \"refers to the type of valuation to be conducted, not the object that is valued.\" The dissenting Justices argued that deciding the case on the basis of textual analysis and comparison to state debt limitations would amount to a \"coin toss.\" In the dissenters' view, Congress's purpose was to set a \"hard cap\" on debt, which would indicate that the debt limitation should be based on the full market (appraised) value of property on Guam rather than dependent on the changeable assessment rate.","sumSrc":"Oyez","by":{"0":"14"}},{"t":"case","label":"Lindahl v. Office of Pers. Mgmt.","cite":"470 U.S. 768","y":1985,"id":"1984/83-5954","sc":1,"sum":"The Office of Personnel Management (OPM) \"determine[s] questions of disability and dependency\" in administering the Federal Government's disability retirement program. 5 U. S. C. § 8347(c). Its \"decisions... concerning these matters are final and conclusive and are not subject to review,\" ibid., except to the extent that administrative review by the Merit Systems Protection Board (MSPB) is provided by §8347(d)(1). …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17"}},{"t":"case","label":"Mach Mining, LLC v. EEOC","cite":"135 S. Ct. 1645","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./135/1645/","sc":1,"op":1,"ar":2,"by":{"0":"4, 11, 17"}},{"t":"case","label":"Mathews v. Eldridge","cite":"424 U.S. 319","y":1976,"id":"1975/74-204","sc":1,"op":2,"sum":"In an 6-to-2 decision, the Court held that the initial termination of Eldridge's benefits without a hearing did not violate due process.","sumSrc":"Oyez","by":{"0":"24","1":"passim","2":"1, 3-4, 16"}},{"t":"case","label":"Pioneer Inv. Servs. Co. v. Brunswick Assocs. Ltd. P’ship","cite":"507 U.S. 380","y":1993,"id":"1992/91-1695","sc":1,"sum":"As unsecured creditors of petitioner-a company seeking relief under Chapter 11 of the Bankruptcy Code-respondents were required to file proofs of claim with the Bankruptcy Court before the deadline, or bar date, established by that court. An August 3, 1989, bar date was included in a \"Notice for Meeting of Creditors\" received from the court by Mark Berlin, an official for respondents. Respondents' attorney was …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16"}},{"t":"case","label":"Pizarro v. Commissioner of Soc. Sec.","cite":"2013 WL 847331","y":2013,"court":"M.D. Fla.","sum":"Upholding a magistrate judge’s conclusion that a dismissal was not based on substantial evidence.","sumSrc":"brief:0","by":{"0":"22"}},{"t":"case","label":"Sackett v. EPA","cite":"566 U.S. 120","y":2012,"id":"2011/10-1062","sc":1,"sum":"The Court found that homeowners have a right to go to court over a Clean Water Act order of the Environmental Protection Agency.","sumSrc":"Oyez","by":{"0":"15","1":"27"}},{"t":"case","label":"SEC v. Chenery Corp.","cite":"318 U.S. 80","y":1943,"id":"scdb/1942-113","sc":1,"op":1,"ar":4,"sum":"By an order of the Securities and Exchange Commission under the Public Utility Holding Company Act of 1935, approval was given, over objections, to a plan for the reorganization of a registered holding company, whereby preferred stock which had been acquired by officers and directors of the company while plans for its reorganization were before the Commission, would not be converted into stock of the reorganized …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25","1":"19, 29","2":"17"}},{"t":"case","label":"Sims v. Apfel","cite":"530 U.S. 103","y":2000,"id":"1999/98-9537","sc":1,"op":5,"ar":1,"sum":"The Court held, 5 to 4, that Social Security claimants who exhaust administrative remedies need not also exhaust issues administratively in order to preserve judicial review of those issues.","sumSrc":"Oyez","by":{"0":"25","1":"4, 25, 34","2":"passim"}},{"t":"case","label":"Smith v. Heckler","cite":"761 F.2d 516","y":1985,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/761/516/","op":1,"by":{"0":"10, 16","1":"16, 17, 33, 38, 39, 42"}},{"t":"case","label":"United States Army Corps of Eng’rs v. Hawkes Co.","cite":"136 S. Ct. 1807","y":2016,"id":"2015/15-290","sc":1,"sum":"The Court determined that the Army Corps of Engineers’ jurisdictional determination that a property constituted “water of the United States” was a final agency action subject to judicial review under the Administrative Procedure Act.","sumSrc":"Oyez","by":{"0":"15"}},{"t":"case","label":"United States v. Carolina Freight Carriers Corp.","cite":"315 U.S. 475","y":1942,"id":"scdb/1941-054","sc":1,"sum":"1. Under the \"grandfather clause\" of the Motor Carrier Act of 1935, the Interstate Commerce Commission's authorization of operation as a common carrier by motor vehicle within a specified \"territory\" may permit service to all points in part of the area and to designated points in other parts.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20"}},{"t":"case","label":"United States v. Gonzales","cite":"520 U.S. 1","y":1997,"id":"1996/95-1605","sc":1,"sum":"In a 7-to-2 decision delivered by Justice Sandra Day O'Connor, the Court announced \"[t]he plain language of (the law) forbids a district court to direct that a term of imprisonment under the statute run concurrently with any other term of imprisonment, whether state or federal.\".","sumSrc":"Oyez","by":{"0":"14"}},{"t":"case","label":"United States v. James","cite":"478 U.S. 597","y":1986,"id":"1985/85-434","sc":1,"sum":"Section 702c bars recovery against the Government in these cases.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"14"}},{"t":"case","label":"Walker v. Commissioner of Soc. Sec.","cite":"2013 WL 3833199","y":2013,"court":"M.D. Fla.","by":{"0":"22"}},{"t":"reg","label":"20 C.F.R. § 404.968","url":"https://www.ecfr.gov/current/title-20/section-404.968","subs":["(b)"],"by":{"0":"8","2":"10"}},{"t":"usc","label":"5 U.S.C. § 704","url":"https://www.law.cornell.edu/uscode/text/5/704","stext":{"head":"§704. Actions reviewable","paras":[[0,"Agency action made reviewable by statute and final agency action for which there is no other adequate remedy in a court are subject to judicial review. A preliminary, procedural, or intermediate agency action or ruling not directly reviewable is subject to review on the review of the final agency action. Except as otherwise expressly required by statute, agency action otherwise final is final for the purposes of this section whether or not there has been presented or determined an application for a declaratory order, for any form of reconsideration, or, unless the agency otherwise requires by rule and provides that the action meanwhile is inoperative, for an appeal to superior agency authority."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/704?type=usc&year=mostrecent&link-type=html"},"head":"§704. Actions reviewable","tname":"Government Organization and Employees","by":{"0":"15","1":"26","2":"4-5"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"usc","label":"42 U.S.C. § 405","url":"https://www.law.cornell.edu/uscode/text/42/405","subs":["(g)","(h)","(a)","(b)(1)","(i)"],"stext":{"head":"§405. Evidence, procedure, and certification for payments","paras":[[0,"(a) Rules and regulations; procedures"],[0,"The Commissioner of Social Security shall have full power and authority to make rules and regulations and to establish procedures, not inconsistent with the provisions of this subchapter, which are necessary or appropriate to carry out such provisions, and shall adopt reasonable and proper rules and regulations to regulate and provide for the nature and extent of the proofs and evidence and the method of taking and furnishing the same in order to establish the right to benefits hereunder."],[0,"(b) Administrative determination of entitlement to benefits; findings of fact; hearings; investigations; evidentiary hearings in reconsiderations of disability benefit terminations; subsequent applications"],[0,"(1) The Commissioner of Social Security is directed to make findings of fact, and decisions as to the rights of any individual applying for a payment under this subchapter. Any such decision by the Commissioner of Social Security which involves a determination of disability and which is in whole or in part unfavorable to such individual shall contain a statement of the case, in understandable language, setting forth a discussion of the evidence, and stating the Commissioner's determination and the reason or reasons upon which it is based. Upon request by any such individual or upon request by a wife, divorced wife, widow, surviving divorced wife, surviving divorced mother, surviving divorced father, husband, divorced husband, widower, surviving divorced husband, child, or parent who makes a showing in writing that his or her rights may be prejudiced by any decision the Commissioner of Social Security has rendered, the Commissioner shall give such applicant and such other individual reasonable notice and opportunity for a hearing with respect to such decision, and, if a hearing is held, shall, on the basis of evidence adduced at the hearing, affirm, modify, or reverse the Commissioner's findings of fact and such decision. Any such request with respect to such a decision must be filed within sixty days after notice of such decision is received by the individual making such request. The Commissioner of Social Security is further authorized, on the Commissioner's own motion, to hold such hearings and to conduct such investigations and other proceedings as the Commissioner may deem necessary or proper for the administration of this subchapter. In the course of any hearing, investigation, or other proceeding, the Commissioner may administer oaths and affirmations, examine witnesses, and receive evidence. Evidence may be received at any hearing before the Commissioner of Social Security even though inadmissible under rules of evidence applicable to court procedure."],[0,"(2) In any case where—"],[1,"(A) an individual is a recipient of disability insurance benefits, or of child's, widow's, or widower's insurance benefits based on disability,"],[1,"(B) the physical or mental impairment on the basis of which such benefits are payable is found to have ceased, not to have existed, or to no longer be disabling, and"],[1,"(C) as a consequence of the finding described in subparagraph (B), such individual is determined by the Commissioner of Social Security not to be entitled to such benefits,"],[0,"any reconsideration of the finding described in subparagraph (B), in connection with a reconsideration by the Commissioner of Social Security (before any hearing under paragraph (1) on the issue of such entitlement) of the Commissioner's determination described in subparagraph (C), shall be made only after opportunity for an evidentiary hearing, with regard to the finding described in subparagraph (B), which is reasonably accessible to such individual. Any reconsideration of a finding described in subparagraph (B) may be made either by the State agency or the Commissioner of Social Security where the finding was originally made by the State agency, and shall be made by the Commissioner of Social Security where the finding was originally made by the Commissioner of Social Security. In the case of a reconsideration by a State agency of a finding described in subparagraph (B) which was originally made by such State agency, the evidentiary hearing shall be held by an adjudicatory unit of the State agency other than the unit that made the finding described in subparagraph (B). In the case of a reconsideration by the Commissioner of Social Security of a finding described in subparagraph (B) which was originally made by the Commissioner of Social Security, the evidentiary hearing shall be held by a person other than the person or persons who made the finding described in subparagraph (B)."],[0,"(3)(A) A failure to timely request review of an initial adverse determination with respect to an application for any benefit under this subchapter or an adverse determination on reconsideration of such an initial determination shall not serve as a basis for denial of a subsequent application for any benefit under this subchapter if the applicant demonstrates that the applicant, or any other individual referred to in paragraph (1), failed to so request such a review acting in good faith reliance upon incorrect, incomplete, or misleading information, relating to the consequences of reapplying for benefits in lieu of seeking review of an adverse determination, provided by any officer or employee of the Social Security Administration or any State agency acting under section 421 of this title."],[0,"(B) In any notice of an adverse determination with respect to which a review may be requested under paragraph (1), the Commissioner of Social Security shall describe in clear and specific language the effect on possible entitlement to benefits under this subchapter of choosing to reapply in lieu of requesting review of the determination."],[0,"(c) Wage records"],[0,"(1) For the purposes of this subsection—"],[1,"(A) The term \"year\" means a calendar year when used with respect to wages and a taxable year when used with respect to self-employment income."],[1,"(B) The term \"time limitation\" means a period of three years, three months, and fifteen days."],[1,"(C) The term \"survivor\" means an individual's spouse, surviving divorced wife, surviving divorced husband, surviving divorced mother, surviving divorced father, child, or parent, who survives such individual."],[1,"(D) The term \"period\" when used with respect to self-employment income means a taxable year and when used with respect to wages means—"],[2,"(i) a quarter if wages were reported or should have been reported on a quarterly basis on tax returns filed with the Secretary of the Treasury or his delegate under section 6011 of the Internal Revenue Code of 1986 or regulations thereunder (or on reports filed by a State under section 418(e) 1 of this title (as in effect prior to December 31, 1986) or regulations thereunder),"],[2,"(ii) a year if wages were reported or should have been reported on a yearly basis on such tax returns or reports, or"],[2,"(iii) the half year beginning January 1 or July 1 in the case of wages which were reported or should have been reported for calendar year 1937."],[0,"(2)(A) On the basis of information obtained by or submitted to the Commissioner of Social Security, and after such verification thereof as the Commissioner deems necessary, the Commissioner of Social Security shall establish and maintain records of the amounts of wages paid to, and the amounts of self-employment income derived by, each individual and of the periods in which such wages were paid and such income was derived and, upon request, shall inform any individual or his survivor, or the legal representative of such individual or his estate, of the amounts of wages and self-employment income of such individual and the periods during which such wages were paid and such income was derived, as shown by such records at the time of such request."],[0,"(B)(i) In carrying out the Commissioner's duties under subparagraph (A) and subparagraph (F), the Commissioner of Social Security shall take affirmative measures to assure that social security account numbers will, to the maximum extent practicable, be assigned to all members of appropriate groups or categories of individuals by assigning such numbers (or ascertaining that such numbers have already been assigned):"],[1,"(I) to aliens at the time of their lawful admission to the United States either for permanent residence or under other authority of law permitting them to engage in employment in the United States and to other aliens at such time as their status is so changed as to make it lawful for them to engage in such employment;"],[1,"(II) to any individual who is an applicant for or recipient of benefits under any program financed in whole or in part from Federal funds including any child on whose behalf such benefits are claimed by another person; and"],[1,"(III) to any other individual when it appears that he could have been but was not assigned an account number under the provisions of subclauses (I) or (II) but only after such investigation as is necessary to establish to the satisfaction of the Commissioner of Social Security, the identity of such individual, the fact that an account number has not already been assigned to such individual, and the fact that such individual is a citizen or a noncitizen who is not, because of his alien status, prohibited from engaging in employment;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/405?type=usc&year=mostrecent&link-type=html"},"op":2,"ar":1,"head":"§405. Evidence, procedure, and certification for payments","tname":"The Public Health and Welfare","by":{"0":"passim, 2","1":"27, 27, 27, passim, 2, 3, 4, 10, 12","2":"7-8"}},{"t":"case","label":"Adams v. Heckler","cite":"799 F.2d 131","y":1986,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/799/131/","op":1,"by":{"1":"16"}},{"t":"case","label":"Athens Cmty. Hosp., Inc. v. Schweiker","cite":"686 F.2d 989","y":1982,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/686/989/","by":{"1":"31"}},{"t":"case","label":"(III) Cases—Continued: Auburn Reg’l Med. Ctr. v. Sebelius","cite":"642 F.3d 1145","y":2011,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/642/1145/","by":{"1":"31, 33"}},{"t":"case","label":"Bacon v. Sullivan","cite":"969 F.2d 1517","y":1992,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/969/1517/","op":1,"by":{"1":"16, 33"}},{"t":"case","label":"Bowen v. Galbreath","cite":"485 U.S. 74","y":1988,"id":"1987/86-1146","sc":1,"op":1,"sum":"A district court does not have the authority to order the Secretary to withhold a portion of past-due SSI benefits for the payment of attorney's fees received in judicial proceedings under Title XVI. Pp. 75-79. 799 F. 2d 370, reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"2"}},{"t":"case","label":"Bowen v. Yuckert","cite":"482 U.S. 137","y":1987,"id":"1986/85-1409","sc":1,"sum":"The Social Security Act (Act) defines \"disability\" as the \"inability to engage in any substantial gainful activity by reason of any medically determinable physical or mental impairment....\" 42 U. S. C. § 423(d)(1)(A). The Act also provides that an individual \"shall be determined to be under a disability only if his... impairment [is] of such severity that he is not only unable to do his previous work but cannot, …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"41"}},{"t":"case","label":"Callender v. SSA","cite":"275 Fed. Appx. 174","y":2008,"court":"3d Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./275/174/","by":{"1":"45"}},{"t":"case","label":"Chicago & S. Air Lines, Inc. v. Waterman S.S. Corp.","cite":"333 U.S. 103","y":1948,"id":"scdb/1947-037","sc":1,"by":{"1":"27"}},{"t":"case","label":"Consolidated Edison Co. v. NLRB","cite":"305 U.S. 197","y":1938,"id":"scdb/1938-001","sc":1,"sum":"1. The power of the Federal Government, and the provisions of the National Labor Relations Act, extend to the labor relations of public utilities engaged in supplying electrical energy, gas and steam, where the business and activities of the utilities are wholly within a State, and where the quantum of service rendered to customers for strictly intrastate uses is vast and greatly preponderant, but where, …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"44"}},{"t":"case","label":"Cox v. Benefits Review Bd.","cite":"791 F.2d 445","y":1986,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/791/445/","by":{"1":"31"}},{"t":"case","label":"Dexter v. Colvin","cite":"731 F.3d 977","y":2013,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/731/977/","by":{"1":"45"}},{"t":"case","label":"Dickinson v. Zurko","cite":"527 U.S. 150","y":1999,"id":"1998/98-377","sc":1,"sum":"The Court held that the Court of Appeals for the Federal Circuit must use the framework set forth in the Administrative Procedure Act when reviewing PTO findings of fact.","sumSrc":"Oyez","by":{"1":"44"}},{"t":"case","label":"Dietsch v. Schweiker","cite":"700 F.2d 865","y":1983,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/700/865/","op":1,"sum":"Holding that review under Section 405(g) is unavailable and that review can be obtained only through a writ of mandamus.","sumSrc":"brief:1","by":{"1":"16, 33"}},{"t":"case","label":"Dillow v. Sullivan","cite":"952 F.2d 1396","y":1992,"court":"4th Cir. Dec. 5","url":"https://www.courtlistener.com/c/F.2d/952/1396/","by":{"1":"33"}},{"t":"case","label":"Farzana K. v. Indiana Dep’t of Educ.","cite":"473 F.3d 703","y":2007,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/473/703/","by":{"1":"31"}},{"t":"case","label":"Harper ex rel. Harper v. Bowen","cite":"813 F.2d 737","y":1987,"url":"https://www.courtlistener.com/c/F.2d/813/737/","op":1,"by":{"1":"16, 33"}},{"t":"case","label":"Higgs v. Attorney Gen. of the U.S.","cite":"655 F.3d 333","y":2011,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/655/333/","by":{"1":"31"}},{"t":"case","label":"Hilmes v. Secretary of Health & Human Servs.","cite":"983 F.2d 67","y":1993,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/983/67/","sum":"Holding judicial review of dismissal of request for ALJ hearing is not available because no “hearing” has occurred.","sumSrc":"brief:1","by":{"1":"15, 37"}},{"t":"case","label":"ICC v. Brotherhood of Locomotive Eng’rs","cite":"482 U.S. 270","y":1987,"id":"1986/85-792","sc":1,"op":1,"sum":"In October 1982, petitioner Interstate Commerce Commission (ICC or Commission) issued an order, which, inter alia, granted petitioner Missouri-Kansas-Texas Railroad Co. and another railroad the right to conduct operations using the tracks of a third, newly consolidated carrier. In April 1983, respondent Brotherhood of Locomotive Engineers (BLE) filed a \"Petition for Clarification\" asking the ICC to declare that the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"27"}},{"t":"case","label":"INS v. Elias-Zacarias","cite":"502 U.S. 478","y":1992,"id":"1991/90-1342","sc":1,"sum":"A guerrilla organization's attempt to coerce a person into performing military service does not necessarily constitute \"persecution on account of... political opinion\" under § 101(a)(42) of the Immigration and Nationality Act, 8 U. S. C. §1101(a)(42). Even one who supports the political aims of a guerrilla movement might resist military combat and thus become the object of such coercion. Moreover, persecution on …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"44"}},{"t":"case","label":"Khan v. U.S. Dep’t of Justice","cite":"494 F.3d 255","y":2007,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/494/255/","by":{"1":"31"}},{"t":"case","label":"Loya v. Desert Sands Unified Sch. Dist.","cite":"721 F.2d 279","y":1983,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/721/279/","by":{"1":"31"}},{"t":"case","label":"Loyd v. Sullivan","cite":"882 F.2d 218","y":1989,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/882/218/","sum":"Noting that “the decision to grant an extension rests within the discretion of the Secretary” and reviewing the decision for abuse of discretion.","sumSrc":"brief:1","by":{"1":"44"}},{"t":"case","label":"Magwood v. Patterson","cite":"561 U.S. 320","y":2010,"id":"2009/09-158","sc":1,"sum":"The Court held that, when a habeas corpus application alleges new judgment for the first time, it is not \"second or successive\" under the Antiterrorism and Effective Death Penalty Act and is therefore constitutional.","sumSrc":"Oyez","by":{"1":"25"}},{"t":"case","label":"Matlock v. Sullivan","cite":"908 F.2d 492","y":1990,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/908/492/","op":1,"sum":"Finding that the agency had no “final decision[ ] * * * made after a hearing” because “the Appeals Council may deny a request for an extension without a hearing”.","sumSrc":"brief:1","by":{"1":"16, 33, 35, 38, 40","2":"14"}},{"t":"case","label":"Port of Boston Marine Terminal Ass’n v. Rederiaktiebolaget Transatlantic","cite":"400 U.S. 62","y":1970,"id":"1970/99","sc":1,"sum":"Petitioner Terminal Association, a maritime terminal operators conference. operating under an agreement approved by the Federal Maritime Commission (FMC), pursuant to §.15 of the Shipping Act, 1916, revised a tariff on file with the agency by shifting the incidence of a wharf demuri'age charge from consignees to carriers. When several carriers refused to pay the revised charge, which -had not previously been …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"27"}},{"t":"case","label":"Republic of Argentina v. Weltover, Inc.","cite":"504 U.S. 607","y":1992,"id":"1991/91-763","sc":1,"sum":"The Court held that the District Court properly asserted jurisdiction under the FSIA.","sumSrc":"Oyez","by":{"1":"25"}},{"t":"case","label":"Richardson v. Perales","cite":"402 U.S. 389","y":1971,"id":"1970/108","sc":1,"sum":"Written reports by physicians who have examined claimant for disability insurance benefits under Social Security Act constitute \"substantial evidence\" supporting a nondisability finding within the standard of § 205 (g) of the Act, notwithstanding the reports' hearsay character, the absence of cross-examination (through claimant's failure to exercise his subpoena rights), and the directly opposing testimony by the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"43"}},{"t":"case","label":"Rothman v. Secretary of Health & Human Servs.","cite":"70 F.3d 110","y":1994,"court":"1st Cir. Dec. 8","url":"https://www.courtlistener.com/c/F.3d/70/110/","by":{"1":"32"}},{"t":"case","label":"Shalala v. Illinois Council on Long Term Care, Inc.","cite":"529 U.S. 1","y":2000,"id":"1999/98-1109","sc":1,"sum":"The Court held that the Medicare Act barred federal-question jurisdiction of the Council's challenges to the validity of various Medicare regulations. The Court concluded that the Council must proceed instead through the special review channel that the Medicare statutes create.","sumSrc":"Oyez","by":{"1":"24"}},{"t":"case","label":"Sheehan v. Secretary of Health, Educ. & Welfare","cite":"593 F.2d 323","y":1979,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/593/323/","sum":"Holding that Appeals Council dismissal was not reviewable.","sumSrc":"brief:1","by":{"1":"21"}},{"t":"case","label":"Taniguchi v. Kan Pac. Saipan, Ltd.","cite":"566 U.S. 560","y":2012,"id":"2011/10-1472","sc":1,"sum":"The Court held that the winner of a federal-court lawsuit cannot be reimbursed by the losing party for any document translation costs under 28 U.S.C. § 1920(6).","sumSrc":"Oyez","by":{"1":"25"}},{"t":"case","label":"Weinberger v. Salfi","cite":"422 U.S. 749","y":1975,"id":"1974/74-214","sc":1,"op":4,"sum":"Explaining that exhaustion serves to “preven[t] premature interference with agency processes” and to give the agency “an opportunity to correct its own errors,” “to afford the parties and the courts the benefit of its experience and expertise,” and to produce “a record which is adequate for judicial review”.","sumSrc":"opinion","by":{"1":"passim","2":"14-16"}},{"t":"const","label":"Amendment V","clauses":[["due-process-5","Due Process Clause (Fifth Amendment)"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"1":"14"}},{"t":"usc","label":"5 U.S.C. § 551","url":"https://www.law.cornell.edu/uscode/text/5/551","by":{"1":"26, 27"}},{"t":"usc","label":"42 U.S.C. § 301","url":"https://www.law.cornell.edu/uscode/text/42/301","by":{"1":"2"}},{"t":"usc","label":"42 U.S.C. § 401","url":"https://www.law.cornell.edu/uscode/text/42/401","stext":{"head":"§401. Trust Funds","paras":[[0,"(a) Federal Old-Age and Survivors Insurance Trust Fund"],[0,"There is hereby created on the books of the Treasury of the United States a trust fund to be known as the \"Federal Old-Age and Survivors Insurance Trust Fund\". The Federal Old-Age and Survivors Insurance Trust Fund shall consist of the securities held by the Secretary of the Treasury for the Old-Age Reserve Account and the amount standing to the credit of the Old-Age Reserve Account on the books of the Treasury on January 1, 1940, which securities and amount the Secretary of the Treasury is authorized and directed to transfer to the Federal Old-Age and Survivors Insurance Trust Fund, and, in addition, such gifts and bequests as may be made as provided in subsection (i)(1), and such amounts as may be appropriated to, or deposited in, the Federal Old-Age and Survivors Insurance Trust Fund as hereinafter provided. There is hereby appropriated to the Federal Old-Age and Survivors Insurance Trust Fund for the fiscal year ending June 30, 1941, and for each fiscal year thereafter, out of any moneys in the Treasury not otherwise appropriated, amounts equivalent to 100 per centum of—"],[1,"(1) the taxes (including interest, penalties, and additions to the taxes) received under subchapter A of chapter 9 of the Internal Revenue Code of 1939 (and covered into the Treasury) which are deposited into the Treasury by collectors of internal revenue before January 1, 1951; and"],[1,"(2) the taxes certified each month by the Commissioner of Internal Revenue as taxes received under subchapter A of chapter 9 of such Code which are deposited into the Treasury by collectors of internal revenue after December 31, 1950, and before January 1, 1953, with respect to assessments of such taxes made before January 1, 1951; and"],[1,"(3) the taxes imposed by subchapter A of chapter 9 of such Code with respect to wages (as defined in section 1426 of such Code), and by chapter 21 (other than sections 3101(b) and 3111(b)) of the Internal Revenue Code of 1954 with respect to wages (as defined in section 3121 of such Code) reported to the Commissioner of Internal Revenue pursuant to section 1420(c) of the Internal Revenue Code of 1939 after December 31, 1950, or to the Secretary of the Treasury or his delegates pursuant to subtitle F of the Internal Revenue Code of 1954 after December 31, 1954, as determined by the Secretary of the Treasury by applying the applicable rates of tax under such subchapter or chapter 21 (other than sections 3101(b) and 3111(b)) to such wages, which wages shall be certified by the Commissioner of Social Security on the basis of the records of wages established and maintained by such Commissioner in accordance with such reports, less the amounts specified in clause (1) of subsection (b) of this section; and"],[1,"(4) the taxes imposed by subchapter E of chapter 1 of the Internal Revenue Code of 1939, with respect to self-employment income (as defined in section 481 of such Code), and by chapter 2 (other than section 1401(b)) of the Internal Revenue Code of 1954 with respect to self-employment income (as defined in section 1402 of such Code) reported to the Commissioner of Internal Revenue on tax returns under such subchapter or to the Secretary of the Treasury or his delegate on tax returns under subtitle F of such Code, as determined by the Secretary of the Treasury by applying the applicable rate of tax under such subchapter or chapter (other than section 1401(b)) to such self-employment income, which self-employment income shall be certified by the Commissioner of Social Security on the basis of the records of self-employment income established and maintained by the Commissioner of Social Security in accordance with such returns, less the amounts specified in clause (2) of subsection (b) of this section."],[0,"The amounts appropriated by clauses (3) and (4) of this subsection shall be transferred from time to time from the general fund in the Treasury to the Federal Old-Age and Survivors Insurance Trust Fund, and the amounts appropriated by clauses (1) and (2) of subsection (b) shall be transferred from time to time from the general fund in the Treasury to the Federal Disability Insurance Trust Fund, such amounts to be determined on the basis of estimates by the Secretary of the Treasury of the taxes, specified in clauses (3) and (4) of this subsection, paid to or deposited into the Treasury; and proper adjustments shall be made in amounts subsequently transferred to the extent prior estimates were in excess of or were less than the taxes specified in such clauses (3) and (4) of this subsection. All amounts transferred to either Trust Fund under the preceding sentence shall be invested by the Managing Trustee in the same manner and to the same extent as the other assets of such Trust Fund. Notwithstanding the preceding sentence, in any case in which the Secretary of the Treasury determines that the assets of either such Trust Fund would otherwise be inadequate to meet such Fund's obligations for any month, the Secretary of the Treasury shall transfer to such Trust Fund on the first day of such month the amount which would have been transferred to such Fund under this section as in effect on October 1, 1990; and such Trust Fund shall pay interest to the general fund on the amount so transferred on the first day of any month at a rate (calculated on a daily basis, and applied against the difference between the amount so transferred on such first day and the amount which would have been transferred to the Trust Fund up to that day under the procedures in effect on January 1, 1983) equal to the rate earned by the investments of such Fund in the same month under subsection (d)."],[0,"(b) Federal Disability Insurance Trust Fund"],[0,"There is hereby created on the books of the Treasury of the United States a trust fund to be known as the \"Federal Disability Insurance Trust Fund\". The Federal Disability Insurance Trust Fund shall consist of such gifts and bequests as may be made as provided in subsection (i)(1), and such amounts as may be appropriated to, or deposited in, such fund as provided in this section. There is hereby appropriated to the Federal Disability Insurance Trust Fund for the fiscal year ending June 30, 1957, and for each fiscal year thereafter, out of any moneys in the Treasury not otherwise appropriated, amounts equivalent to 100 per centum of—"],[1,"(1)(A) ½ of 1 per centum of the wages (as defined in section 3121 of the Internal Revenue Code of 1954) paid after December 31, 1956, and before January 1, 1966, and reported to the Secretary of the Treasury or his delegate pursuant to subtitle F of the Internal Revenue Code of 1954, (B) 0.70 of 1 per centum of the wages (as so defined) paid after December 31, 1965, and before January 1, 1968, and so reported, (C) 0.95 of 1 per centum of the wages (as so defined) paid after December 31, 1967, and before January 1, 1970, and so reported, (D) 1.10 per centum of the wages (as so defined) paid after December 31, 1969, and before January 1, 1973, and so reported, (E) 1.1 per centum of the wages (as so defined) paid after December 31, 1972, and before January 1, 1974, and so reported, (F) 1.15 per centum of the wages (as so defined) paid after December 31, 1973, and before January 1, 1978, and so reported, (G) 1.55 per centum of the wages (as so defined) paid after December 31, 1977, and before January 1, 1979, and so reported, (H) 1.50 per centum of the wages (as so defined) paid after December 31, 1978, and before January 1, 1980, and so reported, (I) 1.12 per centum of the wages (as so defined) paid after December 31, 1979, and before January 1, 1981, and so reported, (J) 1.30 per centum of the wages (as so defined) paid after December 31, 1980, and before January 1, 1982, and so reported, (K) 1.65 per centum of the wages (as so defined) paid after December 31, 1981, and before January 1, 1983, and so reported, (L) 1.25 per centum of the wages (as so defined) paid after December 31, 1982, and before January 1, 1984, and so reported, (M) 1.00 per centum of the wages (as so defined) paid after December 31, 1983, and before January 1, 1988, and so reported, (N) 1.06 per centum of the wages (as so defined) paid after December 31, 1987, and before January 1, 1990, and so reported, (O) 1.20 per centum of the wages (as so defined) paid after December 31, 1989, and before January 1, 1994, and so reported, (P) 1.88 per centum of the wages (as so defined) paid after December 31, 1993, and before January 1, 1997, and so reported, (Q) 1.70 per centum of the wages (as so defined) paid after December 31, 1996, and before January 1, 2000, and so reported, (R) 1.80 per centum of the wages (as so defined) paid after December 31, 1999, and before January 1, 2016, and so reported, (S) 2.37 per centum of the wages (as so defined) paid after December 31, 2015, and before January 1, 2019, and so reported, and (T) 1.80 per centum of the wages (as so defined) paid after December 31, 2018, and so reported,,1 which wages shall be certified by the Commissioner of Social Security on the basis of the records of wages established and maintained by such Commissioner in accordance with such reports; and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/401?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§401. Trust Funds","tname":"The Public Health and Welfare","by":{"1":"2, 3, 4"}},{"t":"usc","label":"42 U.S.C. § 1381","url":"https://www.law.cornell.edu/uscode/text/42/1381","stext":{"head":"§1381. Statement of purpose; authorization of appropriations","paras":[[0,"For the purpose of establishing a national program to provide supplemental security income to individuals who have attained age 65 or are blind or disabled, there are authorized to be appropriated sums sufficient to carry out this subchapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1381?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1381. Statement of purpose; authorization of appropriations","tname":"The Public Health and Welfare","by":{"1":"2, 3, 4, 10, 12"}},{"t":"usc","label":"42 U.S.C. § 1383","url":"https://www.law.cornell.edu/uscode/text/42/1383","subs":["(c)(1)(A)","(c)(3)","(d)(1)"],"stext":{"head":"§1383. Procedure for payment of benefits","paras":[[0,"(a) Time, manner, form, and duration of payments; representative payees; promulgation of regulations"],[0,"(1) Benefits under this subchapter shall be paid at such time or times and (subject to paragraph (10)) in such installments as will best effectuate the purposes of this subchapter, as determined under regulations (and may in any case be paid less frequently than monthly where the amount of the monthly benefit would not exceed $10)."],[0,"(2)(A)(i) Payments of the benefit of any individual may be made to any such individual or to the eligible spouse (if any) of such individual or partly to each."],[0,"(ii)(I) Upon a determination by the Commissioner of Social Security that the interest of such individual would be served thereby, such payments shall be made, regardless of the legal competency or incompetency of the individual or eligible spouse, to another individual, or an organization, with respect to whom the requirements of subparagraph (B) have been met (in this paragraph referred to as such individual's \"representative payee\") for the use and benefit of the individual or eligible spouse."],[0,"(II) In the case of an individual eligible for benefits under this subchapter by reason of disability, the payment of such benefits shall be made to a representative payee if the Commissioner of Social Security determines that such payment would serve the interest of the individual because the individual also has an alcoholism or drug addiction condition (as determined by the Commissioner) and the individual is incapable of managing such benefits."],[0,"(iii) If the Commissioner of Social Security or a court of competent jurisdiction determines that the representative payee of an individual or eligible spouse has misused any benefits which have been paid to the representative payee pursuant to clause (ii) or section 405(j)(1) or 1007 of this title, the Commissioner of Social Security shall promptly terminate payment of benefits to the representative payee pursuant to this subparagraph, and provide for payment of benefits to an alternative representative payee of the individual or eligible spouse or, if the interest of the individual under this subchapter would be served thereby, to the individual or eligible spouse."],[0,"(iv) For purposes of this paragraph, misuse of benefits by a representative payee occurs in any case in which the representative payee receives payment under this subchapter for the use and benefit of another person and converts such payment, or any part thereof, to a use other than for the use and benefit of such other person. The Commissioner of Social Security may prescribe by regulation the meaning of the term \"use and benefit\" for purposes of this clause."],[0,"(B)(i) Any determination made under subparagraph (A) for payment of benefits to the representative payee of an individual or eligible spouse shall be made on the basis of—"],[1,"(I) an investigation by the Commissioner of Social Security of the person to serve as representative payee, which shall be conducted in advance of such payment, and shall, to the extent practicable, include a face-to-face interview with such person; and"],[1,"(II) adequate evidence that such payment is in the interest of the individual or eligible spouse (as determined by the Commissioner of Social Security in regulations)."],[0,"(ii) As part of the investigation referred to in clause (i)(I), the Commissioner of Social Security shall—"],[1,"(I) require the person being investigated to submit documented proof of the identity of such person, unless information establishing such identity was submitted with an application for benefits under subchapter II, subchapter VIII, or this subchapter;"],[1,"(II) verify the social security account number (or employer identification number) of such person;"],[1,"(III) determine whether such person has been convicted of a violation of section 408, 1011, or 1383a of this title;"],[1,"(IV) obtain information concerning whether the person has been convicted of any other offense under Federal or State law which resulted in imprisonment for more than 1 year;"],[1,"(V) obtain information concerning whether such person is a person described in section 1382(e)(4)(A) of this title;"],[1,"(VI) determine whether payment of benefits to such person has been terminated pursuant to subparagraph (A)(iii), whether the designation of such person as a representative payee has been revoked pursuant to section 1007(a) of this title, and whether certification of payment of benefits to such person has been revoked pursuant to section 405(j) of this title, by reason of misuse of funds paid as benefits under subchapter II, subchapter VIII, or this subchapter, and"],[1,"(VII) determine whether such person has been convicted (and not subsequently exonerated), under Federal or State law, of a felony provided under clause (xv), or of an attempt or a conspiracy to commit such a felony."],[0,"(iii) Benefits of an individual may not be paid to any other person pursuant to subparagraph (A)(ii) if—"],[1,"(I) such person has previously been convicted as described in clause (ii)(III);"],[1,"(II) except as provided in clause (iv), payment of benefits to such person pursuant to subparagraph (A)(ii) has previously been terminated as described in clause (ii)(VI), the designation of such person as a representative payee has been revoked pursuant to section 1007(a) of this title, or certification of payment of benefits to such person under section 405(j) of this title has previously been revoked as described in section 405(j)(2)(B)(i)(VI) of this title;"],[1,"(III) except as provided in clause (v), such person is a creditor of such individual who provides such individual with goods or services for consideration;"],[1,"(IV) the person has previously been convicted as described in clause (ii)(IV) of this subparagraph, unless the Commissioner determines that the payment would be appropriate notwithstanding the conviction;"],[1,"(V) such person is a person described in section 1382(e)(4)(A) of this title,"],[1,"(VI) except as provided in clause (xvii), such person has previously been convicted (and not subsequently exonerated) as described in clause (ii)(VII), or"],[1,"(VII) such person's benefits under this subchapter, subchapter II, or subchapter VIII are certified for payment to a representative payee during the period for which the individual's benefits would be certified for payment to another person."],[0,"(iv) The Commissioner of Social Security shall prescribe regulations under which the Commissioner of Social Security may grant an exemption from clause (iii)(II) to any person on a case-by-case basis if such exemption would be in the best interest of the individual or eligible spouse whose benefits under this subchapter would be paid to such person pursuant to subparagraph (A)(ii)."],[0,"(v) Clause (iii)(III) shall not apply with respect to any person who is a creditor referred to therein if such creditor is—"],[1,"(I) a relative of such individual if such relative resides in the same household as such individual;"],[1,"(II) a legal guardian or legal representative of such individual;"],[1,"(III) a facility that is licensed or certified as a care facility under the law of a State or a political subdivision of a State;"],[1,"(IV) a person who is an administrator, owner, or employee of a facility referred to in subclause (III) if such individual resides in such facility, and the payment of benefits under this subchapter to such facility or such person is made only after good faith efforts have been made by the local servicing office of the Social Security Administration to locate an alternative representative payee to whom the payment of such benefits would serve the best interests of such individual; or"],[1,"(V) an individual who is determined by the Commissioner of Social Security, on the basis of written findings and under procedures which the Commissioner of Social Security shall prescribe by regulation, to be acceptable to serve as a representative payee."],[0,"(vi) The procedures referred to in clause (v)(V) shall require the individual who will serve as representative payee to establish, to the satisfaction of the Commissioner of Social Security, that—"],[1,"(I) such individual poses no risk to the beneficiary;"],[1,"(II) the financial relationship of such individual to the beneficiary poses no substantial conflict of interest; and"],[1,"(III) no other more suitable representative payee can be found."],[0,"(vii) In the case of an individual described in subparagraph (A)(ii)(II), when selecting such individual's representative payee, preference shall be given to—"],[1,"(I) a certified community-based nonprofit social service agency (as defined in subparagraph (I));"],[1,"(II) a Federal, State, or local government agency whose mission is to carry out income maintenance, social service, or health care-related activities;"],[1,"(III) a State or local government agency with fiduciary responsibilities; or"],[1,"(IV) a designee of an agency (other than of a Federal agency) referred to in the preceding subclauses of this clause, if the Commissioner of Social Security deems it appropriate,"],[0,"unless the Commissioner of Social Security determines that selection of a family member would be appropriate."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1383?type=usc&year=mostrecent&link-type=html"},"ar":1,"head":"§1383. Procedure for payment of benefits","tname":"The Public Health and Welfare","by":{"1":"4, 4, 4"}},{"t":"usc","label":"28 U.S.C. § 1291","url":"https://www.law.cornell.edu/uscode/text/28/1291","by":{"1":"31, 32"}},{"t":"rule","label":"Fed. R. Civ. P. 59","url":"https://www.law.cornell.edu/rules/frcp/rule_59","subs":["(e)"],"by":{"1":"15"}},{"t":"reg","label":"25 Fed. Reg. 1677","url":"https://www.govinfo.gov/link/fr/25/1677","by":{"1":"9"}},{"t":"reg","label":"45 Fed. Reg. 52,078","url":"https://www.govinfo.gov/link/fr/45/52078","by":{"1":"9"}},{"t":"reg","label":"64 Fed. Reg. 57,687","url":"https://www.govinfo.gov/link/fr/64/57687","by":{"1":"9, 40"}},{"t":"reg","label":"81 Fed. Reg. 14,438","url":"https://www.govinfo.gov/link/fr/81/14438","by":{"1":"7, 8"}},{"t":"case","label":"Bell v. Hood","cite":"327 U.S. 678","y":1946,"id":"scdb/1945-042","sc":1,"sum":"1. Where the complaint seeks recovery squarely on the ground of violation of plaintiffs' rights under the Fourth and Fifth Amendments, a federal district court has jurisdiction of a suit against agents of the Federal Government to recover damages in excess of $3,000 alleged to have been suffered by the plaintiffs as a result of such violations-even though neither the Constitution nor the Congress has provided for …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"5"}},{"t":"case","label":"Booth v. Churner","cite":"532 U.S. 731","y":2001,"id":"2000/99-1964","sc":1,"sum":"The Court held that even though the prison grievance procedure did not provide for requested monetary relief, Booth was nonetheless required to exhaust administrative remedies before filing suit with respect to prison conditions.","sumSrc":"Oyez","by":{"2":"4"}},{"t":"case","label":"Bowen v. Massachusetts","cite":"487 U.S. 879","y":1988,"id":"1987/87-712","sc":1,"sum":"The federal contribution (referred to as a \"reimbursement\") to a State's Medicaid program takes the form of advances based on the State's estimate of its future expenditures for covered services. Overpayments may be withheld from future advances, or, if a disallowance dispute develops, may be retained by the State at its option pending resolution of the dispute. After Massachusetts was reimbursed by the Department …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"4-5"}},{"t":"case","label":"Brown v. Colvin","cite":"825 F.3d 936","y":2016,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/825/936/","by":{"2":"10"}},{"t":"case","label":"Cohen v. Beneficial Indus. Loan Corp.","cite":"337 U.S. 541","y":1949,"id":"scdb/1948-101","sc":1,"sum":"1. Under 28 U. S. C. § 1291, appeal may be. taken from an order of a Federal District Court denying a corporation's motion that the plaintiff in a stockholder's derivative action be required, pursuant to a state statute, to give security for reasonable expenses of the defendants, in connection with the action.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"18"}},{"t":"case","label":"Consolidated Rail Corp. v. Darrone","cite":"465 U.S. 624","y":1984,"id":"1983/82-862","sc":1,"sum":"Section 504 of the Rehabilitation Act of 1973 provides that \"[n]o... handicapped individual... shall, solely by reason of his handicap,... be subjected to discrimination under any program or activity receiving Federal financial assistance.\" Section 505(a)(2), which was added to the Act in 1978, makes \"available\" the \"remedies, procedures, and rights\" set forth in Title VI of the Civil Rights Act of 1964 (Title VI) …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"6"}},{"t":"case","label":"Damato v. Sullivan","cite":"945 F.2d 982","y":1991,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/945/982/","by":{"2":"10"}},{"t":"case","label":"Descamps v. United States","cite":"570 U.S. 254","y":2013,"id":"2012/11-9540","sc":1,"sum":"The Court held that it was improper to apply the categorical approach in which the courts apply elements of a prior conviction with elements of a generic crime in order to enhance a sentence under the ACCA.","sumSrc":"Oyez","by":{"2":"19"}},{"t":"case","label":"Energy Transfer Partners v. FERC","cite":"567 F.3d 134","y":2009,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/567/134/","by":{"2":"17"}},{"t":"case","label":"Heckler v. Day","cite":"467 U.S. 104","y":1984,"id":"1983/82-1371","sc":1,"sum":"In a 5-to-4 opinion, the Court held that Congress already considered and expressly rejected the imposition of mandatory disability dispute-resolution deadlines. Such deadlines, according to congressional reports, would subordinate quality of service to timeliness.","sumSrc":"Oyez","by":{"2":"6"}},{"t":"case","label":"Heckler v. Ringer","cite":"466 U.S. 602","y":1984,"id":"1983/82-1772","sc":1,"op":2,"sum":"Part A of Title XVIII of the Social Security Act, commonly known as the Medicare Act, provides insurance for the cost of hospital and related posthospital expenses, but precludes reimbursement for services which are not \"reasonable and necessary\" for the diagnosis or treatment of illness or injury. Judicial review of a claim under the Medicare Act is available only after the Secretary of Health and Human Services …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"4"}},{"t":"case","label":"Iames v. Commissioner of Internal Revenue","cite":"850 F.3d 160","y":2017,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/850/160/","by":{"2":"5"}},{"t":"case","label":"INS v. St. Cyr","cite":"533 U.S. 289","y":2001,"id":"2000/00-767","sc":1,"sum":"The Court held that habeas jurisdiction was not repealed by AEDPA and IIRIRA.","sumSrc":"Oyez","by":{"2":"16"}},{"t":"case","label":"Jones v. Bock","cite":"549 U.S. 199","y":2007,"id":"2006/05-7058","sc":1,"ar":1,"sum":"The Court ruled unanimously that the Sixth Circuit's rules for exhaustion of administrative remedies were not required by the Prisoner Litigation Reform Act. The opinion by Chief Justice John Roberts held that prisoners bring civil rights lawsuits do not need to demonstrate that they have already exhausted all administrative remedies.","sumSrc":"Oyez","by":{"2":"4-5, 19"}},{"t":"case","label":"K Mart Corp. v. Cartier, Inc.","cite":"486 U.S. 281","y":1988,"id":"1987/86-495","sc":1,"sum":"The judgment is affirmed in part and reversed in part. 252 U. S. App. D. C. 342, 790 F. 2d 903, affirmed in part and reversed in part. JUSTICE KENNEDY delivered the opinion of the Court as to Parts I, II-A, and II-C, concluding that:","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"7"}},{"t":"case","label":"LeFande v. District of Columbia","cite":"841 F.3d 485","y":2016,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/841/485/","by":{"2":"17"}},{"t":"case","label":"McCarthy v. Madigan","cite":"503 U.S. 140","y":1992,"id":"1991/90-6861","sc":1,"sum":"Exhaustion of the Bureau of Prisons' administrative procedure is not required before a federal prisoner can initiate a Bivens action solely for money damages.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"4, 18"}},{"t":"case","label":"Ramah Navajo Chapter v. Lujan","cite":"112 F.3d 1455","y":1997,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/112/1455/","by":{"2":"16"}},{"t":"case","label":"Steel Co. v. Citizens for a Better Env’t","cite":"523 U.S. 83","y":1998,"id":"1997/96-643","sc":1,"sum":"The Court held, because none of the relief sought would likely remedy its alleged injury in fact, that Citizens For A Better Environment lacked standing to maintain suit and that the Court and lower federal courts lack the jurisdiction to entertain it. While all nine Justices agreed that the organization lacked standing, they disagreed on the reasons.","sumSrc":"Oyez","by":{"2":"5"}},{"t":"case","label":"Stovic v. Railroad Ret. Bd.","cite":"826 F.3d 500","y":2016,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/826/500/","by":{"2":"13"}},{"t":"case","label":"Sullivan v. Hudson","cite":"490 U.S. 877","y":1989,"id":"1988/88-616","sc":1,"op":2,"sum":"Observing that “[a]s provisions for judicial review of agency action go, §405(g) is somewhat unusual” in that its “detailed provisions . . . suggest a degree of direct interaction between a federal court and an administrative agency alien to” APA review.","sumSrc":"opinion","by":{"2":"7, 18"}},{"t":"case","label":"Taylor v. Commissioner of Soc. Sec. Admin.","cite":"659 F.3d 1228","y":2011,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/659/1228/","by":{"2":"10"}},{"t":"case","label":"Teague v. Lane","cite":"489 U.S. 288","y":1989,"id":"1988/87-5259","sc":1,"sum":"The judgment is affirmed. 820 F. 2d 832, affirmed. JUSTICE O'CONNOR delivered the opinion of the Court with respect to Parts I, II, and III, concluding that:","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"9"}},{"t":"case","label":"United States v. Carver","cite":"260 U.S. 482","y":1923,"id":"scdb/1922-063","sc":1,"sum":"1. Under the Maritime Lien and Ship Mortgage Acts, June 23, 1910, c. 373, 36 Stat. 604; June 5, 1920, c. 250, § 30, 41 Stat. 1000, 1005, no hen arises for supplies furnished a chartered vessel where the charter forbids it, and where the material-man, by reasonably diligent investigation, could have ascertained there was a charter and gained knowledge of its terms.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"9"}},{"t":"case","label":"Your Home Visiting Nurse Servs. v. Shalala","cite":"525 U.S. 449","y":1999,"id":"1998/97-1489","sc":1,"ar":18,"sum":"Announced by Justice Antonin Scalia, the Court ruled that the Board does not have jurisdiction to review a fiscal intermediary's refusal to reopen a reimbursement determination. Moreover, the Court held that the federal-question statute and mandamus statute do not entitle Your Home Visiting Nurse to judicial review of the intermediary's reopening decision.","sumSrc":"Oyez","by":{"2":"11-12"}},{"t":"case","label":"Zipes v. Trans World Airlines, Inc.","cite":"455 U.S. 385","y":1982,"id":"1981/78-1545","sc":1,"sum":"In 1970, the union then representing flight attendants employed by respondent Trans World Airlines, Inc. (TWA), brought a federal-court class action alleging that TWA practiced unlawful sex discrimination in violation of Title VII of the Civil Rights Act of 1964 by its policy of grounding all female flight attendants who became mothers while their male counterparts who became fathers were permitted to continue …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"4"}}]};